$commands = @()
$mcp = @()
foreach ($f in $files) {
  Get-Content $f.FullName | ForEach-Object {
    $line = $_
    if ([string]::IsNullOrWhiteSpace($line)) { return }
    try { $obj = $line | ConvertFrom-Json -ErrorAction Stop } catch { return }
    if ($obj.message -and $obj.message.content) {
      foreach ($c in $obj.message.content) {
        if ($c.type -eq 'tool_use') {
          if ($c.name -eq 'Bash') {
            $commands += $c.input.command
          } elseif ($c.name -like 'mcp__*') {
            $mcp += $c.name
          }
        }
      }
    }
  }
}
