23	
24	static void rb_transplant(rbtree_t *t, rb_node_t *u, rb_node_t *v) {
25	    if (u->parent == t->nil) t->root = v;
26	    else if (u == u->parent->left) u->parent->left = v;
27	    else u->parent->right = v;
28	    v->parent = u->parent;
29	}
30	
31	static void rotate_left(rbtree_t *t, rb_node_t *x) {
32	    rb_node_t *y = x->right;
33	    x->right = y->left;
34	    if (y->left != t->nil) y->left->parent = x;
35	    y->parent = x->parent;
36	    if (x->parent == t->nil) t->root = y;
37	    else if (x == x->parent->left) x->parent->left = y;
38	    else x->parent->right = y;
39	    y->left = x;
40	    x->parent = y;
41	}
42	
43	static void rotate_right(rbtree_t *t, rb_node_t *x) {
44	    rb_node_t *y = x->left;
45	    x->left = y->right;
46	    if (y->right != t->nil) y->right->parent = x;
47	    y->parent = x->parent;
48	    if (x->parent == t->nil) t->root = y;
49	    else if (x == x->parent->right) x->parent->right = y;
50	    else x->parent->left = y;
51	    y->right = x;
52	    x->parent = y;
53	}
54	
55	static void rb_delete_fixup(rbtree_t *t, rb_node_t *x) {
56	    /* invariant: every path through x is short exactly one black node;
57	     * every other path already has the correct black-height */
58	    while (x != t->root && x->color == RB_BLACK) {
59	        if (x == x->parent->left) {
60	            rb_node_t *w = x->parent->right;
61	            if (w->color == RB_RED) {
62	                w->color = RB_BLACK;
63	                x->parent->color = RB_RED;
64	                rotate_left(t, x->parent);
65	                w = x->parent->right;
66	            }
67	            if (w->left->color == RB_BLACK && w->right->color == RB_BLACK) {
68	                w->color = RB_RED;
69	                x = x->parent;
70	            } else {
71	                if (w->right->color == RB_BLACK) {
72	                    w->left->color = RB_BLACK;
73	                    w->color = RB_RED;
74	                    rotate_right(t, w);
75	                    w = x->parent->right;
76	                }
77	                w->color = x->parent->color;
78	                x->parent->color = RB_BLACK;
79	                w->right->color = RB_BLACK;
80	                rotate_left(t, x->parent);
81	                x = t->root;
82	            }
83	        } else {
84	            rb_node_t *w = x->parent->left;
85	            if (w->color == RB_RED) {
86	                w->color = RB_BLACK;
87	                x->parent->color = RB_RED;
88	                rotate_right(t, x->parent);
89	                w = x->parent->left;
90	            }
91	            if (w->right->color == RB_BLACK && w->left->color == RB_BLACK) {
92	                w->color = RB_RED;
93	                x = x->parent;
94	            } else {
95	                if (w->left->color == RB_BLACK) {
96	                    w->right->color = RB_BLACK;
97	                    w->color = RB_RED;
98	                    rotate_left(t, w);
99	                    w = x->parent->left;
100	                }
101	                w->color = x->parent->color;
102	                x->parent->color = RB_BLACK;
103	                w->left->color = RB_BLACK;
104	                rotate_right(t, x->parent);
105	                x = t->root;
106	            }
107	        }
108	    }
109	    x->color = RB_BLACK;
110	}
