112	int rb_delete(rbtree_t *t, const char *key) {
113	    rb_node_t *z = find_node(t, key);
114	    if (z == t->nil) return -1;
115	
116	    rb_node_t *y = z;
117	    rb_color_t y_original_color = y->color;
118	    rb_node_t *x;
119	
120	    if (z->left == t->nil) {
121	        x = z->right;
122	        rb_transplant(t, z, z->right);
123	        free(z->key);
124	        if (t->value_free) t->value_free(z->value);
125	        free(z);
126	    } else if (z->right == t->nil) {
127	        x = z->left;
128	        rb_transplant(t, z, z->left);
129	        free(z->key);
130	        if (t->value_free) t->value_free(z->value);
131	        free(z);
132	    } else {
133	        /* Two-children case: copy the in-order successor's key/value into z
134	         * (z never moves), then splice the successor node out of the tree.
135	         * y has at most a right child, since it's a subtree minimum. */
136	        y = tree_minimum(t->nil, z->right);
137	        y_original_color = y->color;
138	        x = y->right;
139	
140	        free(z->key);
141	        if (t->value_free) t->value_free(z->value);
142	        z->key = y->key;
143	        z->value = y->value;
144	        y->key = NULL;
145	        y->value = NULL;
146	
147	        rb_transplant(t, y, x);
148	        free(y);
149	    }
150	
151	    if (y_original_color == RB_BLACK) rb_delete_fixup(t, x);
152	
153	    t->size--;
154	    return 0;
155	}
156	
157	size_t rb_size(const rbtree_t *t) {
158	    return t->size;
159	}
